-- Daily challenges for 2026-11-03: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-03. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('getting-comfortable-on-the-phone', 'Getting Comfortable on the Phone', 'For anyone who puts off phone calls or feels their heart race when the phone rings. Each day is one small step toward calls that feel easier, from jotting a few notes first to dialing, staying kind to yourself and hanging up with a little more confidence.', 'Social Anxiety', 365, array['Social Anxiety', 'Communication', 'Assertiveness']::text[], 1, '2026-11-03T17:00:00+00:00'::timestamptz),
  ('sharing-what-you-know', 'Sharing What You Know', 'For anyone who knows how to do something well, from fixing a bike to baking bread, and would like to pass it on. Each day is one small way to share what you know, teach with patience and enjoy watching someone else learn.', 'Values', 365, array['Values', 'Relationships', 'Self-Esteem']::text[], 1, '2026-11-03T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('getting-comfortable-on-the-phone', 'sharing-what-you-know');

